import "testing"

func TestReverse(t *testing.T) {
	tests := []struct {
		in   string
		want string
	}{
		{"", ""},
		{"a", "a"},
		{"hello", "olleh"},
		{"héllo", "olléh"},
	}

	for _, tt := range tests {
		t.Run(tt.in, func(t *testing.T) {
			got := Reverse(tt.in)
			if got != tt.want {
				t.Errorf("Reverse(%q) = %q; want %q", tt.in, got, tt.want)
			}
		})
	}
}
